import { test, expect } from '@playwright/test';

test.describe('Record Category Assignment via Dropdown', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully assign a category to a record using dropdown', async ({ page }) => {
    // Verify the category dropdown is visible
    const categoryDropdown = page.getByRole('combobox', { name: /category/i });
    await expect(categoryDropdown).toBeVisible();

    // Verify the dropdown contains category options
    const categoryOptions = page.getByRole('option');
    await expect(categoryOptions).toHaveCount(3);

    // Select a category from the dropdown
    const selectedCategory = page.getByRole('option', { name: /category/i, value: /finance/i });
    await selectedCategory.click();

    // Verify the selected category is displayed in the UI
    const categoryLabel = page.getByText(/finance/i);
    await expect(categoryLabel).toBeVisible();

    // Verify the category is assigned to the record
    const recordCategory = page.getByText(/finance/i);
    await expect(recordCategory).toBeVisible();

    // Verify the record has a category icon
    const categoryIcon = page.getByRole('img', { name: /category icon/i });
    await expect(categoryIcon).toBeVisible();

    // Verify the category is reflected in the record details
    const recordDetails = page.getByRole('region', { name: /record details/i });
    await expect(recordDetails).toBeVisible();

    // Verify the category is listed in the record details
    const categoryList = page.getByText(/finance/i);
    await expect(categoryList).toBeVisible();

    // Verify the category is saved in the record
    const recordId = page.getByRole('heading', { name: /record id/i });
    await expect(recordId).toBeVisible();
    const recordIdValue = page.getByText(/record-123/i);
    await expect(recordIdValue).toBeVisible();

    // Verify the category is saved in the database
    const categoryStorage = page.getByRole('status', { name: /category saved/i });
    await expect(categoryStorage).toBeVisible();
  });

  test('should handle invalid category selection and display error message', async ({ page }) => {
    // Verify the category dropdown is visible
    const categoryDropdown = page.getByRole('combobox', { name: /category/i });
    await expect(categoryDropdown).toBeVisible();

    // Verify the dropdown contains category options
    const categoryOptions = page.getByRole('option');
    await expect(categoryOptions).toHaveCount(3);

    // Select an invalid category from the dropdown
    const invalidCategory = page.getByRole('option', { name: /invalid category/i, value: /none/i });
    await invalidCategory.click();

    // Verify the category is not displayed in the UI
    const categoryLabel = page.getByText(/invalid category/i);
    await expect(categoryLabel).not.toBeVisible();

    // Verify the category is not assigned to the record
    const recordCategory = page.getByText(/finance/i);
    await expect(recordCategory).not.toBeVisible();

    // Verify the category is not listed in the record details
    const categoryList = page.getByText(/finance/i);
    await expect(categoryList).not.toBeVisible();

    // Verify the category is not saved in the record
    const recordId = page.getByRole('heading', { name: /record id/i });
    await expect(recordId).toBeVisible();
    const recordIdValue = page.getByText(/record-123/i);
    await expect(recordIdValue).toBeVisible();

    // Verify the category is not saved in the database
    const categoryStorage = page.getByRole('status', { name: /category saved/i });
    await expect(categoryStorage).not.toBeVisible();

    // Verify the error message is displayed
    const errorMessage = page.getByText(/invalid category/i);
    await expect(errorMessage).toBeVisible();
  });
});
